import unittest
from candidate import concatenate


class TestConcatenate(unittest.TestCase):
    def test_concatenate_normal_case(self):
        self.assertEqual(concatenate(['a', 'b', 'c']), 'abc')

    def test_concatenate_empty_list(self):
        self.assertEqual(concatenate([]), '')

    def test_concatenate_single_element_list(self):
        self.assertEqual(concatenate(['x']), 'x')

    def test_concatenate_list_with_one_empty_string(self):
        self.assertEqual(concatenate(['']), '')

    def test_concatenate_list_with_multiple_empty_strings(self):
        self.assertEqual(concatenate(['', '', '']), '')

    def test_concatenate_long_list_of_strings(self):
        strings = ['char' + str(i) for i in range(100)]
        result = concatenate(strings)
        self.assertEqual(len(result), 400)

    def test_concatenate_strings_with_spaces_and_special_chars(self):
        self.assertEqual(concatenate([' hello ', 'world!', '@#$', '']), ' hello world! @#$')

    def test_concatenate_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            concatenate(None)

    def test_concatenate_list_with_integers_raises_type_error(self):
        with self.assertRaises(TypeError):
            concatenate([1, 2, 3])

    def test_concatenate_unicode_strings(self):
        self.assertEqual(concatenate(['α', 'β', 'γ']), 'αβγ')

    def test_concatenate_single_space_string(self):
        self.assertEqual(concatenate([' ']), ' ')

    def test_concatenate_mixed_case_letters(self):
        self.assertEqual(concatenate(['A', 'b', 'C']), 'AbC')

    def test_concatenate_strings_with_newlines(self):
        self.assertEqual(concatenate(['line1\n', 'line2\n']), 'line1\nline2\n')


if __name__ == '__main__':
    unittest.main()
